"use client";

import Features from "@/components/product/Features";
import ProductBreadcrumb from "@/components/product/ProductBreadcrumb";
import ProductNotFound from "@/components/product/ProductNotFound";
import RelatedProducts from "@/components/product/RelatedProducts";
import ShareProduct from "@/components/product/ShareProduct";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { useCart } from "@/context/CartContext";
import { useFavorites } from "@/context/FavoritesContext";
import { cn, formatVND, productImageUrl } from "@/lib/utils";
import type { Product } from "@/types/product";
import { Check, Heart, Minus, Plus, ShoppingCart, Star } from "lucide-react";
import Image from "next/image";
import { useParams, useRouter } from "next/navigation";
import { useEffect, useState } from "react";

export default function ProductPage() {
  const { addToCart } = useCart();
  const { toggleFavorite, isFavorite } = useFavorites();
  const { productId } = useParams();
  const router = useRouter();
  const [product, setProduct] = useState<Product | undefined>();
  const [isLoadingProduct, setIsLoadingProduct] = useState(true);
  const [quantity, setQuantity] = useState(1);
  const [isAdding, setIsAdding] = useState(false);
  const [justAdded, setJustAdded] = useState(false);

  useEffect(() => {
    let isMounted = true;

    fetch(`/api/products/${productId}`)
      .then(async (response) => {
        if (!response.ok) throw new Error("Không tải được sản phẩm.");
        return response.json();
      })
      .then((data: Product) => {
        if (isMounted) setProduct(data);
      })
      .catch(() => {
        if (isMounted) setProduct(undefined);
      })
      .finally(() => {
        if (isMounted) setIsLoadingProduct(false);
      });

    return () => {
      isMounted = false;
    };
  }, [productId]);

  if (isLoadingProduct) {
    return (
      <div className="container mx-auto px-4 py-24 text-center text-muted-foreground">
        Đang tải sản phẩm...
      </div>
    );
  }

  if (!product) {
    return <ProductNotFound />;
  }

  const stock = product.stock ?? 100;
  const isOutOfStock = stock <= 0 || product.status === "inactive";
  const isLiked = isFavorite(product.id);
  const imageUrl = productImageUrl(product.image);

  const handleAddToCart = async () => {
    if (isOutOfStock) return;

    setIsAdding(true);
    await new Promise((resolve) => setTimeout(resolve, 300));

    for (let index = 0; index < quantity; index++) {
      addToCart({
        id: product.id,
        name: product.name,
        price: product.price,
        image: imageUrl,
        quantity: 1,
        stock,
      });
    }

    setIsAdding(false);
    setJustAdded(true);
    setTimeout(() => setJustAdded(false), 2000);
  };

  const handleBuyNow = async () => {
    await handleAddToCart();
    if (!isOutOfStock) {
      setTimeout(() => router.push("/cart"), 300);
    }
  };

  const handleQuantityChange = (type: "increment" | "decrement") => {
    if (type === "increment") {
      setQuantity((prev) => Math.min(stock || 1, prev + 1));
    } else {
      setQuantity((prev) => Math.max(1, prev - 1));
    }
  };

  return (
    <div className="container mx-auto px-4 sm:px-6 lg:px-8 py-8">
      <ProductBreadcrumb />

      <div className="grid lg:grid-cols-2 gap-12 mb-16">
        <div className="space-y-4">
          <div className="w-full max-w-[500px] mx-auto flex flex-col items-center px-4">
            <div className="relative rounded-xl shadow-lg overflow-hidden mb-4 w-full">
              {isOutOfStock && (
                <div className="absolute left-4 top-4 z-10 rounded-md bg-slate-950 px-3 py-1.5 text-sm font-semibold text-white">
                  Hết hàng
                </div>
              )}
              <Image
                src={imageUrl}
                alt={product.name}
                width={600}
                height={600}
                priority
                fetchPriority="high"
                className={cn(
                  "rounded-xl object-cover w-full h-auto max-h-[500px]",
                  isOutOfStock && "opacity-60 grayscale"
                )}
              />
            </div>
          </div>
        </div>

        <div className="space-y-6">
          <h1 className="text-3xl lg:text-4xl font-bold text-foreground mb-4">
            {product.name}
          </h1>

          <div className="flex items-center gap-2 mb-4">
            <div className="flex items-center gap-1">
              {[...Array(5)].map((_, index) => (
                <Star key={index} className="h-4 w-4 fill-primary text-primary" />
              ))}
            </div>
            <span className="text-sm text-muted-foreground">(4.8) - 127 đánh giá</span>
          </div>

          <div className="flex flex-wrap items-center gap-3">
            <span className="text-3xl font-bold text-foreground">
              {formatVND(product.price)}
            </span>
            <span
              className={cn(
                "rounded-md px-3 py-1 text-sm font-semibold",
                isOutOfStock ? "bg-slate-100 text-slate-700" : "bg-orange-100 text-orange-700"
              )}
            >
              {isOutOfStock ? "Hết hàng" : "Còn hàng"}
            </span>
          </div>

          <p className="text-muted-foreground leading-relaxed">
            {product.description}
          </p>

          <Separator />

          <div className="space-y-4">
            <div>
              <label className="text-sm font-medium text-foreground mb-2 block">
                Số lượng
              </label>
              <div className="flex items-center gap-3">
                <div className="flex items-center border border-border rounded-lg">
                  <Button
                    variant="ghost"
                    size="icon"
                    onClick={() => handleQuantityChange("decrement")}
                    disabled={quantity <= 1 || isOutOfStock}
                    className="h-10 w-10 rounded-r-none"
                  >
                    <Minus className="h-4 w-4" />
                  </Button>
                  <span className="px-4 py-2 min-w-[60px] text-center font-medium">
                    {quantity}
                  </span>
                  <Button
                    variant="ghost"
                    size="icon"
                    onClick={() => handleQuantityChange("increment")}
                    disabled={isOutOfStock || quantity >= stock}
                    className="h-10 w-10 rounded-l-none"
                  >
                    <Plus className="h-4 w-4" />
                  </Button>
                </div>
              </div>
            </div>

            <div className="flex flex-col sm:flex-row gap-4">
              <Button
                size="lg"
                className={cn(
                  "flex-1 transition-all duration-300",
                  isOutOfStock
                    ? "bg-slate-300 text-slate-600 hover:bg-slate-300"
                    : justAdded
                      ? "bg-green-600 text-white hover:bg-green-600"
                      : "bg-primary text-primary-foreground hover:bg-primary/90"
                )}
                onClick={handleAddToCart}
                disabled={isAdding || isOutOfStock}
              >
                {isOutOfStock ? (
                  <div className="flex items-center gap-2">
                    <ShoppingCart className="h-4 w-4" />
                    Hết hàng
                  </div>
                ) : isAdding ? (
                  <div className="flex items-center gap-2">
                    <div className="w-4 h-4 border-2 border-current border-t-transparent rounded-full animate-spin" />
                    Đang thêm...
                  </div>
                ) : justAdded ? (
                  <div className="flex items-center gap-2">
                    <Check className="h-4 w-4" />
                    Đã thêm vào giỏ!
                  </div>
                ) : (
                  <div className="flex items-center gap-2">
                    <ShoppingCart className="h-4 w-4" />
                    Thêm vào giỏ
                  </div>
                )}
              </Button>

              <Button
                size="lg"
                variant="outline"
                onClick={handleBuyNow}
                disabled={isOutOfStock}
                className="flex-1"
              >
                Mua ngay
              </Button>
            </div>

            <div className="flex flex-col sm:flex-row sm:items-center gap-3">
              <Button
                variant="ghost"
                size="sm"
                onClick={() => toggleFavorite(product)}
                className={cn(
                  "w-fit text-muted-foreground hover:text-foreground",
                  isLiked && "text-destructive"
                )}
              >
                <Heart className={cn("h-4 w-4 mr-2", isLiked && "fill-current")} />
                {isLiked ? "Đã thêm yêu thích" : "Thêm vào yêu thích"}
              </Button>

              <ShareProduct
                productId={product.id}
                productName={product.name}
                productImage={imageUrl}
              />
            </div>
          </div>
        </div>
      </div>

      <Features />
      <RelatedProducts product={product} />
    </div>
  );
}
